do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-101';
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: The Old Testament Story$j$, $j${"prompt": "Write an essay of at least 500 words titled The Old Testament Story. Using what you learned in the six units, trace the thread of God's promise from Genesis to Malachi. Your essay must include: (1) an introduction that states your main idea; (2) at least one event or person from each of the five sections of the Old Testament, which are the Law, the historical books, poetry and wisdom, the major prophets and the minor prophets; (3) at least three verses quoted from the King James Version, with the book, chapter and verse; (4) an explanation of how the Old Testament points to Jesus Christ; and (5) a conclusion that tells what the story means for your own life.", "rubric": "Total 100. Clear main idea and introduction: 10. Covers all five sections with accurate events or people: 25. At least three King James Version verses quoted with references: 20. Explains how the Old Testament points to Jesus Christ: 20. Conclusion and personal application: 10. Organization, clear writing and correct conventions: 15."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: The Old Testament Story$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Old Testament Survey$j$, $j${"questions": [{"q": "What does the word Genesis mean?", "options": ["Judges", "Laws", "Beginnings", "Journeys"]}, {"q": "What did God promise Abram in Genesis 12?", "options": ["A palace in Egypt", "A land, a great nation and a blessing to all families of the earth", "A throne in Babylon", "A kingdom ruled by Pharaoh"]}, {"q": "What is the name of the night when the destroyer passed over the houses marked with blood?", "options": ["Pentecost", "Passover", "Purim", "Jubilee"]}, {"q": "The first five books of the Bible are called:", "options": ["The Law", "The Gospels", "The Writings", "The Prophets"]}, {"q": "Who led Israel across the Jordan River into the promised land?", "options": ["David", "Samuel", "Joshua", "Moses"]}, {"q": "What repeated pattern fills the book of Judges?", "options": ["Peace, harvest, feast, rest", "Sin, oppression, a cry for help, deliverance", "Teaching, exile, return, rest", "War, treaty, trade, peace"]}, {"q": "Who was anointed king after God rejected Saul?", "options": ["David", "Samuel", "Jonathan", "Solomon"]}, {"q": "What did God promise David in 2 Samuel 7?", "options": ["That his throne would be established for ever", "That he would build the ark", "That he would live in Egypt", "That he would never face an enemy"]}, {"q": "Which empire carried Judah into exile and burned the temple?", "options": ["Greece", "Egypt", "Rome", "Babylon"]}, {"q": "Which book tells how God protected the Jewish people in Persia?", "options": ["Ruth", "Nehemiah", "Esther", "Ezra"]}, {"q": "Which book asks why good people suffer?", "options": ["Judges", "Job", "Ruth", "Proverbs"]}, {"q": "Psalm 119:105 says God's word is:", "options": ["A rock in the desert", "A lamp unto my feet, and a light unto my path", "A sword and a shield", "A river in a dry land"]}, {"q": "According to Proverbs 1:7, what is the beginning of knowledge?", "options": ["Hard work", "The fear of the LORD", "Wealth", "Education alone"]}, {"q": "According to Ecclesiastes 12:13, what is the whole duty of man?", "options": ["Build wealth", "Avoid all work", "Rule well", "Fear God and keep his commandments"]}, {"q": "Which prophet answered, Here am I; send me?", "options": ["Isaiah", "Ezekiel", "Jeremiah", "Daniel"]}, {"q": "Which prophet is called the weeping prophet?", "options": ["Daniel", "Ezekiel", "Jeremiah", "Isaiah"]}, {"q": "What did Micah 6:8 say the LORD requires?", "options": ["To fight his enemies", "To bring many sacrifices", "To do justly, love mercy and walk humbly with God", "To build a temple"]}, {"q": "What does Habakkuk 2:4 say the just shall do?", "options": ["Live by his faith", "Build an altar", "Flee from trouble", "Wait for kings"]}, {"q": "Which prophet said the ruler of Israel would come from Bethlehem?", "options": ["Joel", "Nahum", "Micah", "Amos"]}, {"q": "According to Luke 24:44, the law, the prophets and the psalms were written concerning:", "options": ["Jesus Christ", "The kings of Judah", "The temple", "The Greek empire"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Old Testament Survey$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,1,0,2,1,0,0,3,2,1,1,1,3,0,2,2,0,2,0}'::int[], array[$j$Genesis means beginnings.$j$,$j$God promised Abram a land, a great nation and a blessing to the world.$j$,$j$God said, when I see the blood, I will pass over you.$j$,$j$Genesis through Deuteronomy are the Law, or the Pentateuch.$j$,$j$Joshua led Israel into the land after Moses died.$j$,$j$Israel sinned, suffered, cried out, and a judge delivered them.$j$,$j$Samuel anointed David, the youngest son of Jesse.$j$,$j$God promised David an everlasting house, kingdom and throne.$j$,$j$Babylon under Nebuchadnezzar took Judah into exile.$j$,$j$Esther risked her life and God saved His people from Haman's plot.$j$,$j$Job wrestles with suffering and the wisdom of God.$j$,$j$Psalm 119:105 uses the picture of a lamp and a light.$j$,$j$The fear of the LORD is the beginning of knowledge.$j$,$j$The conclusion of the whole matter is to fear God and keep His commandments.$j$,$j$Isaiah answered God's call in Isaiah 6:8.$j$,$j$Jeremiah grieved over the fall of Jerusalem.$j$,$j$Micah 6:8 summarizes what is good.$j$,$j$The just shall live by his faith.$j$,$j$Micah 5:2 names Bethlehem Ephratah.$j$,$j$Jesus said that all things written in the law, the prophets and the psalms concerned Him.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Old Testament Survey$j$ on conflict (item_id) do nothing;
end
$seed$;
